/* ---- k2c01 · bản đồ Siberia, thợ săn bật sáng rồi trôi về phía đông ---- */
DANGKY({
  id: "k2c01", steps: 0,
  say: ["Và cái tin đó làm cả vùng Siberia bỏ việc."],
  html: K2.bdLop() + '<div class="hud">' + K2.nhanVung("k2c01-sb", "SIBERIA") + '</div>',
  anim: root => {
    const sv = root.querySelector("svg.bd"); K2.bd(sv, "k2c01");
    K2.to(sv.__ng, "#C8553D", .58);
    K2.sang(sv, "k2c01", [[59.4,143.2,34],[52.3,104.3,30],[62.0,129.7,26]]);
    const g = el("g", {}, sv.__g), cham = [];
    for (let i = 0; i < 80; i++)
      cham.push(el("circle", { cx:0, cy:0, r:(2.0 + rn(i,15) * 1.9).toFixed(2),
        fill:"#F7C77E", opacity:0 }, g));
    return c => {
      const u = ez(c.u);
      K2.nhipDen(sv, c.t);
      ngam(sv, lerp(300,392,u) + 7 * Math.sin(c.t * .31), lerp(246,252,u) + 4 * Math.cos(c.t * .25),
           lerp(650,566,u) * (1 + .01 * Math.sin(c.t * .19)));
      cham.forEach((e, i) => {
        const tre = rn(i,13) * 1.3, s = c.t - .2 - tre;
        const p = K2.P(52 + rn(i,11) * 19, 88 + rn(i,12) * 74 + ezo(s / 3.4) * 8);
        set(e, { cx:p[0].toFixed(1), cy:p[1].toFixed(1) });
        op(e, (ez(s / .5) * (.42 + .52 * rn(i,14))).toFixed(3));
      });
      ghim("k2c01-sb", sv, K2.P(60, 108), -140, -12);
      kh("k2c01-sb", c.t, .55, 1e9);
    };
  }
});

/* ---- k2c02 · mũi tên cong vượt biển, ba trạm mọc ---- */
DANGKY({
  id: "k2c02", steps: 0,
  say: ["Thợ săn Nga vượt biển sang, lập trạm, rồi lập làng."],
  html: K2.bdLop(),
  anim: root => {
    const sv = root.querySelector("svg.bd"); K2.bd(sv, "k2c02");
    K2.to(sv.__ng, "#C8553D", .5);
    K2.sang(sv, "k2c02", [[53.0,158.7,30],[53.9,-166.5,26],[57.8,-152.4,26]]);
    const g = el("g", {}, sv.__g);
    const a = K2.P(56.2, 161.0), b = K2.P(57.4, -152.6);
    const mt = el("path", { d:"M" + a[0].toFixed(1) + "," + a[1].toFixed(1) +
        " Q" + ((a[0]+b[0])/2).toFixed(1) + "," + (Math.min(a[1],b[1]) - 96).toFixed(1) +
        " " + b[0].toFixed(1) + "," + b[1].toFixed(1),
      fill:"none", stroke:"#F2A33C", "stroke-width":7, "stroke-linecap":"round" }, g);
    const dau = el("polygon", { points:"0,-9 17,0 0,9", fill:"#F2A33C", opacity:0 }, g);
    const tram = [K2.D.unalaska, K2.D.kodiak, K2.D.sitka].map(d => {
      const p = K2.P(d[0], d[1]);
      return el("circle", { cx:p[0].toFixed(1), cy:p[1].toFixed(1), r:4.6,
        fill:"#FFF0CE", stroke:"#07131E", "stroke-width":1.6, opacity:0 }, g);
    });
    return c => {
      const u = ez(c.u);
      ngam(sv, lerp(500,610,u) + 6 * Math.sin(c.t * .34), lerp(300,300,u),
           lerp(820,700,u) * (1 + .012 * Math.sin(c.t * .22)));
      K2.nhipDen(sv, c.t);
      K2.net(mt, 7, sv);
      const w = ezo(cl(c.t / 1.9, 0, 1));
      K2.veDan(mt, w);
      const L = mt.__L || mt.getTotalLength(), q = mt.getPointAtLength(L * Math.max(.01, w));
      const q2 = mt.getPointAtLength(L * Math.max(.02, w) - 3);
      set(dau, { transform:"translate(" + q.x.toFixed(1) + " " + q.y.toFixed(1) + ") rotate(" +
        (Math.atan2(q.y - q2.y, q.x - q2.x) * 180 / Math.PI).toFixed(1) + ")" });
      op(dau, ez((w - .8) / .18));
      tram.forEach((e, i) => op(e, ez((c.t - 1.5 - i * .45) / .4)));
    };
  }
});

